package com.yuegang.zhihui.notification.api;
import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.notification.application.NotificationService;import com.yuegang.zhihui.notification.security.NotificationSecurity;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/notifications")public final class NotificationAdministrationController{private final NotificationService service;private final NotificationSecurity security;public NotificationAdministrationController(NotificationService s,NotificationSecurity x){service=s;security=x;}@GetMapping("/dead-letters")ApiResponse<List<NotificationDeadLetterView>>dead(HttpServletRequest r){security.require(r,"notification:compensate");return ApiResponse.success(service.deadLetters(),TraceIdResolver.resolve(r));}@PostMapping("/send")ApiResponse<AdminSendNotificationResult>send(@Valid @RequestBody AdminSendNotificationRequest command,HttpServletRequest r){security.require(r,"notification:compensate");var message=service.create(new NotificationCommand("manual-"+UUID.randomUUID().toString().replace("-",""),command.userId(),command.templateCode(),command.variables()));int sent=service.dispatchPending();return ApiResponse.success(new AdminSendNotificationResult(message.id(),message.status(),sent),TraceIdResolver.resolve(r));}@PostMapping("/dead-letters/{id}/replay")ApiResponse<Map<String,Boolean>>replay(@PathVariable String id,HttpServletRequest r){service.replay(id,security.require(r,"notification:compensate"));return ApiResponse.success(Map.of("accepted",true),TraceIdResolver.resolve(r));}@PostMapping("/dispatch")ApiResponse<Map<String,Integer>>dispatch(HttpServletRequest r){security.require(r,"notification:compensate");return ApiResponse.success(Map.of("sent",service.dispatchPending()),TraceIdResolver.resolve(r));}}
